def points_for(customer: Customer, spend_cents: int) -> int:
    """Points earned on a purchase: whole units of currency x tier rate. Refunds (negative spend) earn 0."""
    if spend_cents <= 0:
        return 0
    return (spend_cents // 100) * EARN_RATES.get(customer.tier, 1)

